using System.Text.Json;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Returns the list of configured API endpoints")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Name = "Users", Url = "https://api.example.com/users", Method = "GET" },
            new { Name = "Orders", Url = "https://api.example.com/orders", Method = "GET" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'AppName')")] string key)
    {
        var configMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["AppName"] = "ConfigMcpServer",
            ["Version"] = "1.0.0",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30"
        };

        return configMap.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", configMap.Keys)}";
    }

    [McpServerTool(ReadOnly = true), Description("List all available configuration keys")]
    public static string ListConfigKeys()
    {
        var keys = new[] { "AppName", "Version", "MaxRetries", "TimeoutSeconds" };
        return JsonSerializer.Serialize(keys);
    }
}

